import {floraSpecies,validateSpecies} from './flora-species.js';
import {generateSpecies,approveSpecies} from './flora-authoring.js';
import {createFloraPreview} from './flora-preview.js';
import {loadImpostorPackage} from './octahedral-impostor.js';
const $=id=>document.getElementById(id),key='rfl-flora-drafts-v1';let collection=structuredClone(floraSpecies),current,generated,preview,ticket=0;
const say=text=>$('status').textContent=text,fail=e=>say('Error: '+e.message),golden=()=>floraSpecies.some(s=>s.id===current?.id);
const hex=c=>'#'+c.map(x=>Math.round(x*255).toString(16).padStart(2,'0')).join('');
const rgb=h=>[1,3,5].map(i=>parseInt(h.slice(i,i+2),16)/255);
function library(){const filter=$('search').value.toLowerCase();$('library').replaceChildren();for(const s of collection.filter(s=>(s.name+' '+s.category).toLowerCase().includes(filter))){const b=document.createElement('button'),small=document.createElement('small');small.textContent=s.category||'CUSTOM';b.append(small,document.createTextNode(s.name.replace('Nauptre · ','')));b.className=s.id===current?.id?'active':'';b.onclick=()=>select(s);$('library').append(b);}}
function settings(){preview.setSettings({yaw:+$('yaw').value,pitch:+$('pitch').value,zoom:+$('zoom').value,light:+$('light').value,reference:$('reference').value,representation:$('representation').value});$('scale-label').hidden=$('reference').value==='none';}
function select(s){current=s;delete current.approval;library();$('name').value=s.name;$('title').textContent=s.name.replace('Nauptre · ','');$('category').textContent=s.category;$('badge').textContent=golden()?'GOLDEN REFERENCE':'DRAFT / UNAPPROVED';$('fields').disabled=golden();$('name').disabled=golden();$('seed').replaceChildren();for(const seed of s.seeds){const o=document.createElement('option');o.value=seed;o.textContent=seed;$('seed').append(o);}$('growth').hidden=s.recipe.kind!=='growth';$('domain').value=s.rendering.sampling;$('biomes').value=s.ecology.biomes.join(', ');for(const k of ['bark','leaf','flower']){$(k).value=hex(s.palette[k]);$(k).disabled=s.recipe.kind!=='growth';}for(const k of ['depth','forks','spread','foliage','flowers'])$(k).value=s.recipe[k]??({depth:2,forks:3,spread:.6,foliage:1,flowers:0}[k]);$('custom-seed').value=s.seeds[0];$('representation').value='mesh';rebuild();}
function rebuild(){try{generated=generateSpecies(current,+$('seed').value);preview.setCapture(null);++ticket;preview.setMesh(generated.mesh);$('plant-height').value=generated.height.toFixed(3);$('height').textContent=generated.height.toFixed(2);$('triangles').textContent=generated.diagnostics.triangles;$('variants').textContent=current.seeds.length;$('sampling').textContent=current.rendering.sampling==='sphere'?'360°':'HEMI';$('view-label').textContent=golden()?'APPROVED FORM':'DRAFT FORM';settings();say(golden()?'Golden reference. Duplicate to edit; the original remains unchanged.':'Draft generated. Inspect every variant and angle before approval.');}catch(e){fail(e);}}
function edit(){if(golden())return;try{current.name=$('name').value;current.rendering.sampling=$('domain').value;current.ecology.biomes=$('biomes').value.split(',').map(s=>s.trim()).filter(Boolean);if(current.recipe.kind==='growth'){current.recipe.height=+$('plant-height').value;for(const k of ['depth','forks','spread','foliage','flowers'])current.recipe[k]=+$(k).value;for(const k of ['bark','leaf','flower'])current.palette[k]=rgb($(k).value);const seed=+$('custom-seed').value;current.seeds=[seed];$('seed').replaceChildren(new Option(String(seed),String(seed)));}else current.recipe.heightMeters=+$('plant-height').value;delete current.approval;$('badge').textContent='DRAFT / UNAPPROVED';$('title').textContent=current.name;$('representation').value='mesh';rebuild();library();}catch(e){fail(e);}}
function uniqueID(base){let id=base,i=1;while(collection.some(s=>s.id===id))id=base+'-'+i++;return id;}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
try{preview=createFloraPreview($('canvas'));try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(saved))for(const s of saved){validateSpecies(s);if(!collection.some(x=>x.id===s.id))collection.push(s);}}catch{say('Some local drafts could not be loaded; import your exported backup.');}
 $('search').oninput=library;$('seed').onchange=()=>{$('representation').value='mesh';rebuild();};
 $('duplicate').onclick=()=>{const s=structuredClone(current);s.id=uniqueID(current.id+'-copy');s.name=current.name+' copy';s.version=1;s.provenance={kind:'derived',source:current.id,sourceVersion:current.version};delete s.approval;collection.push(s);select(s);};
 $('new').onclick=()=>{const s={...structuredClone(floraSpecies[2]),id:uniqueID('new-tree'),name:'Untitled branching tree',version:1,seeds:[42],recipe:{kind:'growth',height:4,depth:2,forks:3,spread:.6,foliage:1,flowers:0},provenance:{kind:'procedural'},ecology:{biomes:['woodland'],aquatic:false,weight:1,maxSlope:.6}};collection.push(s);select(s);};
 for(const id of ['name','plant-height','depth','forks','spread','foliage','flowers','custom-seed','bark','leaf','flower','domain','biomes'])$(id).onchange=edit;
 for(const id of ['yaw','pitch','zoom','light','reference'])$(id).oninput=()=>{try{settings();}catch(e){fail(e);}};
 $('representation').onchange=async()=>{const serial=++ticket;try{if($('representation').value==='impostor'){if(!golden()){ $('representation').value='mesh';settings();say('This draft has no baked package. Approve/export and run the offline baker.');return;}say('Loading approved offline captures…');const index=await fetch('./baked/impostors/index.json').then(r=>{if(!r.ok)throw Error('Missing capture index');return r.json();}),entry=index.models.find(m=>m.id===generated.id);if(!entry)throw Error('No capture for selected variant');const p=await loadImpostorPackage(new URL('./baked/impostors/'+entry.url,location.href),entry.meshHash);if(serial!==ticket)return;const scale=generated.conversion?.multiplier||1;preview.setCapture({...p,center:p.center.map(x=>x*scale),radius:p.radius*scale});say('Existing baseline bake: '+(p.sampling||'sphere')+' / '+p.grid+' × '+p.grid+' views. New exports use the species capture-domain setting.');}else if($('representation').value==='community')say('Seeded arrangement study of this species. Planetary ecology integration is a later milestone.');settings();}catch(e){$('representation').value='mesh';settings();fail(e);}};
 $('save').onclick=()=>{try{for(const s of collection)validateSpecies(s);localStorage.setItem(key,JSON.stringify(collection.filter(s=>!floraSpecies.some(g=>g.id===s.id))));say('Drafts saved in this browser. Export JSON to keep a portable copy.');}catch(e){fail(e);}};
 $('approve').onclick=async()=>{const s=structuredClone(current),serial=ticket;try{$('approve').disabled=true;const approved=await approveSpecies(s);if(serial!==ticket){say('Definition changed during approval. Review and approve again.');return;}download(approved,approved.id+'-approved.json');$('badge').textContent='APPROVED / EXPORTED';say('Approved '+approved.seeds.length+' variant(s). Exported source includes a content-bound approval; offline baking is the next step.');}catch(e){fail(e);}finally{$('approve').disabled=false;}};
 $('import').onclick=()=>$('file').click();$('file').onchange=async()=>{try{const file=$('file').files[0];if(!file)return;if(file.size>25*1024*1024)throw Error('Import limit is 25 MB');let s=JSON.parse(await file.text());if(s.vertices){if(s.units!=='m')throw Error('Imported mesh must explicitly declare units: m');s={...structuredClone(floraSpecies[1]),id:s.id||'imported-plant',name:s.name||'Imported plant',seeds:[0],recipe:{kind:'imported',vertices:s.vertices},provenance:{kind:'imported',filename:file.name}};}validateSpecies(s);s.id=uniqueID(s.id);delete s.approval;for(const seed of s.seeds)generateSpecies(s,seed);collection.push(s);select(s);}catch(e){fail(e);}finally{$('file').value='';}};
 new ResizeObserver(()=>{try{preview.draw();}catch(e){fail(e);}}).observe($('canvas'));select(collection[0]);
}catch(e){fail(e);}
